import CryptoKit
import Foundation

// Mantido somente para compatibilidade do payload legado; não é exibido nem ativado pela UI.
enum ModType: String {
    case hsAlto, hsPescoco, hsPeito, hologramaArmas
}

/// Payloads protegidos contra extração casual do IPA.
/// A descriptografia ocorre somente em memória e o plaintext não é gravado no bundle.
enum ProtectedModPayloadStore {
    enum PayloadError: LocalizedError {
        case unavailable, invalidPayload, decryptionFailed
        var errorDescription: String? {
            switch self {
            case .unavailable: return "Payload protegido indisponível."
            case .invalidPayload: return "Payload protegido inválido."
            case .decryptionFailed: return "Não foi possível abrir o payload protegido."
            }
        }
    }

    private static let key = SymmetricKey(data: Data(base64Encoded: "fTsumhxfgEapt9LD4fBlikxrjg+aLUx7Hj9afJ0LLkA=" )!)
    private static let payloads: [String: String] = [
        "hsAlto": "",
        "hsPescoco": "",
        "hsPeito": "",
        "hologramaArmas": "",
    ]

    static func data(for mod: ModType) throws -> Data {
        guard let encoded = payloads[modKey(for: mod)],
              let combined = Data(base64Encoded: encoded),
              combined.count > 12 else { throw PayloadError.invalidPayload }
        do {
            let nonce = try AES.GCM.Nonce(data: combined.prefix(12))
            let encrypted = Data(combined.dropFirst(12))
            guard encrypted.count > 16 else { throw PayloadError.invalidPayload }
            let ciphertext = encrypted.dropLast(16)
            let tag = encrypted.suffix(16)
            let sealedBox = try AES.GCM.SealedBox(
                nonce: nonce,
                ciphertext: Data(ciphertext),
                tag: Data(tag)
            )
            return try AES.GCM.open(sealedBox, using: key)
        } catch {
            throw PayloadError.decryptionFailed
        }
    }

    private static func modKey(for mod: ModType) -> String {
        switch mod {
        case .hsAlto: return "hsAlto"
        case .hsPescoco: return "hsPescoco"
        case .hsPeito: return "hsPeito"
        case .hologramaArmas: return "hologramaArmas"
        }
    }
}
